// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface DoctorShiba {
    function owner() external view returns (address);
    function pause() external;
    function paused() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for this exploit
        vm.label(TARGET, "DoctorShiba");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get current owner (for reference)
        address currentOwner = DoctorShiba(TARGET).owner();
        console.log("Current owner:", currentOwner);

        // Step 2: Overwrite owner storage slot to become owner
        // In Ownable contract, _owner is the first variable (slot 0)
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwnerValue = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwnerValue);

        // Verify we are now owner
        address newOwner = DoctorShiba(TARGET).owner();
        console.log("New owner:", newOwner);
        require(newOwner == attacker, "Failed to become owner");

        // Step 3: Call pause() as the new owner
        DoctorShiba(TARGET).pause();

        // Step 4: Verify paused is true
        bool isPaused = DoctorShiba(TARGET).paused();
        console.log("Paused:", isPaused);
        require(isPaused == true, "Failed to pause contract");
        assertEq(isPaused, true, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

